# [n, n] mask: 1 where a * b equals the identity, i.e. b is a right inverse of
# a.  Meaningless without an identity, so it is gated to the zero matrix.
def u:inverse_mask(t) {
  "Answer the [n, n] mask marking pairs whose product is the identity, so cell (a, b) says b undoes a.";
  e = u:identity_of(t)
  eq(t, e) * u:has_identity(t)
}

# [n] mask: 1 at each element with a two-sided inverse.
def u:invertible_mask(t) {
  "Answer the [n] mask marking elements that can be undone from both sides.";
  right = reduce(:or, u:inverse_mask(t), 1)
  left = reduce(:or, u:inverse_mask(t), 0)
  right * left
}

def u:has_inverses(t) {
  "Answer 1 when every element has something that undoes it, which is the last law a group needs.";
  reduce(:and, u:invertible_mask(t))
}

# ---------------------------------------------------------------------------
# The other branch: quasigroups and loops
