<script type="module">
import { createRuntime } from '../runtime.js';

const el = id => document.getElementById(id);
const COLORS = ['#7aa2f7', '#f7768e', '#9ece6a', '#e0af68', '#bb9af7', '#7dcfff'];

const course = await (await fetch('lessons.json')).json();
const lessons = course.lessons;

// Which lessons the reader has finished, kept per browser. Losing it costs a
// reader nothing but their place, so a failure to read it is not worth
// reporting -- render as though nothing were done.
function loadDone() {
  try { return new Set(JSON.parse(localStorage.getItem('aa-done') || '[]')); }
  catch (e) { return new Set(); }
}
function saveDone(done) {
  try { localStorage.setItem('aa-done', JSON.stringify([...done])); } catch (e) { /* fine */ }
}

let done = loadDone();
let at = Math.min(lessons.findIndex(l => !done.has(l.id)) + 0, lessons.length - 1);
if (at < 0) at = 0;
let hintsShown = 0;
let picked = null;

const mlpl = createRuntime('../mlpl/index.html');
let library = '';

// Draw a Cayley table the way the Lab does: one colour per element, and a
// value that is not an element marked rather than coloured.
function renderGrid(values, n) {
  if (!values || values.length !== n * n) return '';
  const head = Array.from({ length: n }, (_, i) => `<th>${i}</th>`).join('');
  const rows = Array.from({ length: n }, (_, r) => {
    const cells = Array.from({ length: n }, (_, c) => {
      const v = values[r * n + c];
      const inside = Number.isInteger(v) && v >= 0 && v < n;
      return inside
        ? `<td style="background:${COLORS[v % COLORS.length]}">${v}</td>`
        : `<td class="escaped">!${v}</td>`;
    }).join('');
    return `<tr><th>${r}</th>${cells}</tr>`;
  }).join('');
  return `<table class="cayley"><tr><th></th>${head}</tr>${rows}</table>`;
}

// Pull the table out of the session, if the learner made one called `t`.
function currentTable() {
  const probe = mlpl.eval('t');
  if (probe.failed) return null;
  try {
    const flat = mlpl.evalJson('to_json({n: u:order(t), v: flatten(t)})');
    return flat;
