}

function show() {
  const l = lesson();
  el('where').textContent = `${l.module.toUpperCase()} · ${at + 1} / ${lessons.length}`;
  el('title').textContent = l.title;
  el('prompt').textContent = l.prompt;
  el('verdict').innerHTML = '';
  el('hints').innerHTML = '';
  el('resultPanel').hidden = true;
  el('output').textContent = '';
  el('grid').innerHTML = '';
  hintsShown = 0;
  picked = null;
  el('hint').disabled = !(l.hints && l.hints.length);
  el('prev').disabled = at === 0;
  renderWork();
  renderDots();
}

function verdict(win, why, extra) {
  el('verdict').innerHTML =
    `<div class="verdict ${win ? 'win' : 'lose'}">${win ? '✓ ' : '✗ '}${why}` +
    (extra ? `<div class="witness">${extra}</div>` : '') + `</div>`;
}

async function run() {
  const l = lesson();
  el('run').disabled = true;
  // Each attempt starts from a clean environment with the library loaded, so
  // a previous lesson's definitions cannot make this one appear to pass.
  mlpl.reset();

  let ran;
  if (l.kind === 'predict') {
    if (picked === null) { verdict(false, 'Pick an answer first.'); el('run').disabled = false; return; }
    ran = { display: '', failed: false };
  } else {
    ran = mlpl.eval(el('editor').value);
  }

  el('resultPanel').hidden = false;
  el('output').textContent = ran.display;

  if (ran.failed) {
    verdict(false, 'That did not run.', 'Read the message below — sw-MLPL says exactly where it gave up.');
    el('run').disabled = false;
    return;
  }

  const table = currentTable();
  if (table) el('grid').innerHTML = renderGrid(table.v, table.n);

  if (!l.check) {
    pass(l, 'Run it, look at the result, and move on when you are ready.');
    el('run').disabled = false;
    return;
  }

  let v;
  try {
    v = mlpl.evalJson(l.check.replace('{{answer}}', String(picked === null ? -1 : l.choices[picked])));
  } catch (e) {
    verdict(false, 'The check could not run.', String(e).slice(0, 200));
    el('run').disabled = false;
    return;
  }

  if (v.pass) {
    pass(l, v.why);
  } else {
    const w = (v.a >= 0 && v.b >= 0)
      ? `Look at row ${v.a}, column ${v.b}: it holds ${v.got}.`
      : (v.got >= 0 ? `Got ${v.got}.` : '');
    verdict(false, v.why, w);
  }
  el('run').disabled = false;
}

function pass(l, why) {
  verdict(true, why);
  done.add(l.id);
  saveDone(done);
  renderDots();
}

el('run').onclick = run;
el('hint').onclick = () => {
  const l = lesson();
  if (hintsShown >= l.hints.length) return;
  el('hints').innerHTML += `<div class="hint">${l.hints[hintsShown++]}</div>`;
  if (hintsShown >= l.hints.length) el('hint').disabled = true;
};
el('reveal').onclick = () => {
  const l = lesson();
  if (!l.solution) { el('hints').innerHTML += `<div class="hint">Nothing to solve here — just run it.</div>`; return; }
  if (l.kind === 'predict') el('hints').innerHTML += `<div class="hint">${l.solution}</div>`;
  else { el('editor').value = l.starter.includes('____') || true ? el('editor').value : ''; el('hints').innerHTML += `<div class="hint"><pre>${l.solution}</pre></div>`; }
};
el('reset').onclick = () => { renderWork(); el('verdict').innerHTML = ''; };
el('next').onclick = () => { if (at < lessons.length - 1) { at++; show(); } };
el('prev').onclick = () => { if (at > 0) { at--; show(); } };

show();
