cat > tests/browser/lesson-check.html <<'HTMLEOF'
<!doctype html>
<meta charset="utf-8">
<title>lesson check</title>
<!--
  Every lesson must be completable, and every prediction must have exactly one
  right answer.

  A lesson is data plus an MLPL checker, and neither is exercised by any MLPL
  test: the checker only runs against a learner's submission, in a browser, in
  a session with the library preloaded. So this drives the real course page the
  way a learner does -- typing the lesson's own solution, or clicking each
  choice in turn -- and fails if any lesson cannot be finished.

  It also catches the subtler thing: a prediction where two choices both pass,
  or none does, is a broken question even though nothing errors.

  Driven by scripts/check-learn.
-->
<pre id="out">running</pre>
<script type="module">
import { createRuntime } from '../runtime.js';

const report = { ok: false, lessons: [], note: '' };
const el = document.getElementById('out');

try {
  const course = await (await fetch('../learn/lessons.json', { cache: 'no-store' })).json();
  const mlpl = createRuntime('../mlpl/index.html');
  await mlpl.ready();
  mlpl.prelude(await (await fetch('../learn/algebra.mlpl', { cache: 'no-store' })).text());
  mlpl.prelude(await (await fetch('../learn/grade.mlpl', { cache: 'no-store' })).text());

  // Grade one submission exactly as the course page does.
  function attempt(lesson, source, answerIndex) {
    mlpl.reset();
    if (lesson.setup) {
      const s = mlpl.eval(lesson.setup);
      if (s.failed) return { pass: false, why: 'setup failed: ' + s.display.slice(0, 120) };
    }
    if (source) {
      const r = mlpl.eval(source);
      if (r.failed) return { pass: false, why: 'did not run: ' + r.display.slice(0, 120) };
    }
    if (!lesson.check) return { pass: true, why: 'no check; running is enough' };
    try {
      const v = mlpl.evalJson(lesson.check.replace('{{answer}}', String(answerIndex)));
      return { pass: !!v.pass, why: v.why };
    } catch (e) {
      return { pass: false, why: 'check failed: ' + String(e).slice(0, 120) };
    }
  }

  for (const l of course.lessons) {
    if (l.kind === 'predict') {
      // Exactly one choice must pass. Zero means unanswerable; two means the
      // question does not distinguish its own options.
      const passing = l.choices
        .map((_, i) => attempt(l, '', i))
        .filter(r => r.pass).length;
      report.lessons.push({
        id: l.id, kind: l.kind, ok: passing === 1,
        detail: `${passing} of ${l.choices.length} choices pass; want exactly 1`,
      });
    } else {
      const source = l.solution || l.starter;
      const r = attempt(l, source, -1);
      report.lessons.push({
        id: l.id, kind: l.kind, ok: r.pass,
        detail: r.pass ? (l.solution ? 'solution completes it' : 'runs as given') : r.why,
      });
    }
  }
  report.ok = report.lessons.every(l => l.ok);
} catch (e) {
  report.note = String(e).slice(0, 300);
}
el.textContent = JSON.stringify(report, null, 1);
</script>
HTMLEOF
cat > scripts/check-learn <<'SHEOF'
#!/bin/sh
# Every lesson is completable, and every prediction has exactly one answer.
#
# The lessons are data and their checkers are MLPL expressions that only run
# against a learner's submission, in a browser, in a session with the library
# loaded. No MLPL test can reach them. So this drives the real page.
#
# Skips loudly -- never silently -- when Chrome, node or the bundle is absent.
set -eu

repo_root=$(CDPATH= cd -- "$(dirname -- "$0")/.." && pwd)
bundle=${MLPL_BUNDLE:-$repo_root/../mlpl-live}
work=$repo_root/out/learn-check

# The generated lessons must be current before anything is driven.
"$repo_root/scripts/build-learn" >/dev/null

chrome=${CHROME:-}
if [ -z "$chrome" ]; then
  for c in "/Applications/Google Chrome.app/Contents/MacOS/Google Chrome" \
           /usr/bin/google-chrome /usr/bin/chromium /usr/bin/chromium-browser; do
    [ -x "$c" ] && { chrome=$c; break; }
  done
fi

if [ -z "$chrome" ] || [ ! -f "$bundle/index.html" ] || ! command -v node >/dev/null 2>&1; then
  echo "check-learn: SKIPPING (needs Chrome, node, and a bundle at $bundle)."
  echo "  A pass here does NOT mean the lessons are completable."
  exit 0
fi

rm -rf "$work"
"$repo_root/scripts/build-site" "$work" >/dev/null
mkdir -p "$work/check"
cp "$repo_root/tests/browser/lesson-check.html" "$work/check/index.html"

port=$(python3 -c 'import socket; s=socket.socket(); s.bind(("127.0.0.1",0)); print(s.getsockname()[1]); s.close()')
cdp=$(python3 -c 'import socket; s=socket.socket(); s.bind(("127.0.0.1",0)); print(s.getsockname()[1]); s.close()')

python3 -m http.server "$port" --directory "$work" >/dev/null 2>&1 &
server=$!
"$chrome" --headless=new --disable-gpu --no-sandbox --no-first-run \
  --no-default-browser-check --disable-background-networking \
  --disable-component-update --disable-features=MediaRouter \
  --user-data-dir="$work/chrome" --remote-debugging-port="$cdp" \
  about:blank >/dev/null 2>&1 &
browser=$!
trap 'kill $server $browser 2>/dev/null || true' EXIT
until curl -s -o /dev/null "http://localhost:$cdp/json/version"; do sleep 1; done

node "$repo_root/tests/browser/drive-web-subset.mjs" "$cdp" \
  "http://localhost:$port/check/" > "$work/verdict.json" 2>/dev/null || true

python3 - "$work/verdict.json" <<'PYEOF'
import json, sys

raw = open(sys.argv[1]).read().strip()
if not raw or raw == "running":
    print("check-learn: the harness never finished", file=sys.stderr)
    raise SystemExit(1)
report = json.loads(raw)
if report.get("note"):
    print(f"check-learn: {report['note']}", file=sys.stderr)
for l in report["lessons"]:
    mark = "ok  " if l["ok"] else "FAIL"
    out = sys.stdout if l["ok"] else sys.stderr
    print(f"  {mark} {l['id']:<18} {l['detail']}", file=out)
raise SystemExit(0 if report.get("ok") else 1)
PYEOF

echo "check-learn: every lesson is completable"
SHEOF
chmod +x scripts/check-learn && ./scripts/check-learn

